(function(){
const E=window.Engine, $=s=>document.querySelector(s);
const KEY='varilink-state-v2', AIKEY='varilink-ai-key';
const CONTRACTS=['Lump Sum','Re-measured','Cost Plus','Design & Build','Other'];
const REASONS=['Client email','Design change','Value engineering','Cost saving','RFI','Contractor notice','Site condition','Other'];
const STATUSES=['Draft','Pending AAA','Pending Consultant','Pending Client','Approved','Cancelled'];
const STAGES=['DCR','CR','NoV','VO','Cost Study','Damage Report','Notice of Claim'];
const DOC_SLOTS=['Contract','Particular Conditions','Stamped BOQ','IFT drawings','IFC drawings','Geotechnical report','Specifications','Queries','Cut sheets'];
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n==null||n===''?'-':Number(n).toLocaleString('en-US',{minimumFractionDigits:0,maximumFractionDigits:2});
const uid=p=>p+Math.random().toString(36).slice(2,8);
function load(){try{const s=localStorage.getItem(KEY);if(s)return JSON.parse(s)}catch(e){}return window.sampleState()}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){}}
function getKey(){try{return localStorage.getItem(AIKEY)||''}catch(e){return ''}}
function setKey(v){try{v?localStorage.setItem(AIKEY,v):localStorage.removeItem(AIKEY)}catch(e){}}
let state=load(), view={p:null,k:null,c:null,tab:null}, takeoffRows=null, aiText={};
function P(){return state.projects.find(x=>x.id===view.p)}
function K(){const p=P();return p&&p.packages.find(x=>x.id===view.k)}
function C(){const k=K();return k&&k.changes.find(x=>x.id===view.c)}
function toast(t){const d=document.createElement('div');d.className='toast';d.textContent=t;d.setAttribute('role','status');document.body.append(d);setTimeout(()=>d.remove(),2600)}
function go(v){view={p:v.p||null,k:v.k||null,c:v.c||null,tab:v.tab||null};takeoffRows=null;try{location.hash='v-'+[view.p,view.k,view.c&&view.c.toLowerCase(),view.tab].map(x=>x||'x').join('-')}catch(e){}render();window.scrollTo(0,0)}
function fromHash(){const m=(location.hash||'').match(/^#v-(.+)$/);if(!m)return;const a=m[1].split('-');
  // change ids hold hyphens: p-k-ce-pk01-001-tab
  const p=a[0]==='x'?null:a[0],k=a[1]==='x'?null:a[1];let c=null,tab=a[a.length-1]==='x'?null:a[a.length-1];const mid=a.slice(2,-1).join('-');if(mid&&mid!=='x')c=mid.toUpperCase();view={p,k,c,tab}}

/* ---------- views ---------- */
function crumbs(){const p=P(),k=K(),c=C();const b=[];b.push(`<button data-go="home">Projects</button>`);if(p)b.push(`/ <button data-go="p">${esc(p.name)}</button>`);if(k)b.push(`/ <button data-go="k">${esc(k.code)}</button>`);if(c)b.push(`/ <span>${esc(c.id)}</span>`);return b.join(' ')}
function render(){
  $('#crumbs').innerHTML=crumbs();
  const m=$('#main'),y=window.scrollY;
  if(view.c&&C())m.innerHTML=changeView();else if(view.k&&K())m.innerHTML=packageView();else if(view.p&&P())m.innerHTML=projectView();else m.innerHTML=homeView();
  window.scrollTo(0,y);
}
function homeView(){return `<div class="row between"><div class="stack" style="gap:4px"><h1>Variation and change management</h1><p class="muted">From the first DCR to the approved VO: one record, priced by your contract rules.</p></div>
<div class="row"><button class="btn primary" data-act="newProject">New project</button><label class="btn">Import cost report<input type="file" accept=".xlsx" hidden data-act="importReport"></label><label class="btn">Open project file<input type="file" accept=".json" data-act="importJson" hidden></label><button class="btn" data-act="settings">AI settings</button></div></div>
<div class="scroll"><table><thead><tr><th>Project</th><th>Client</th><th>Packages</th><th class="num">Contract sum</th><th class="num">Cumulative variations</th><th class="num">Open items</th><th></th></tr></thead><tbody>
${state.projects.map(p=>{const s=p.packages.map(E.packageSummary);const open=p.packages.reduce((n,k)=>n+k.changes.filter(c=>{const l=E.latestStage(c);return l&&l.status!=='Approved'&&l.status!=='Cancelled'}).length,0);return `<tr class="link" data-open-project="${p.id}"><td><strong>${esc(p.name)}</strong> ${p.sample?'<span class="sample">Sample data</span>':''}</td><td>${esc(p.client)}</td><td>${p.packages.length}</td><td class="num">${money(s.reduce((a,x)=>a+x.contractSum,0))}</td><td class="num">${money(s.reduce((a,x)=>a+x.cumulative,0))}</td><td class="num">${open}</td><td><button class="ghost btn danger" data-del-project="${p.id}">Delete</button></td></tr>`}).join('')}
</tbody></table></div>
<p class="small muted">Everything you enter stays in this browser. Save a project file to back it up or pass it to a colleague. Use sample or anonymised data only.</p>`}
function projectView(){const p=P(),sums=p.packages.map(k=>({k,s:E.packageSummary(k)}));const t=f=>sums.reduce((a,x)=>a+x.s[f],0);
 return `<div class="row between"><div class="stack" style="gap:4px"><h1>${esc(p.name)}</h1><p class="muted">${esc(p.client)} · ${esc(p.currency)} ${p.sample?'<span class="sample">Sample data</span>':''}</p></div>
 <div class="row"><button class="btn primary" data-act="newPackage">New package</button><button class="btn" data-act="exportProjectLog">Export variation summary</button><button class="btn" data-act="exportJson">Save project file</button></div></div>
 <div class="titleblock"><div><span class="tb-label">Project</span><span class="tb-val">${esc(p.name)}</span></div><div><span class="tb-label">Contract sum</span><span class="tb-val mono">${money(t('contractSum'))}</span></div><div><span class="tb-label">Approved</span><span class="tb-val mono">${money(t('approved'))}</span></div><div><span class="tb-label">Pending</span><span class="tb-val mono">${money(t('pending'))}</span></div><div><span class="tb-label">Adjusted sum</span><span class="tb-val mono">${money(t('adjusted'))}</span></div></div>
 <div class="scroll"><table><thead><tr><th>Package</th><th>Name</th><th>Contractor</th><th>Contract</th><th class="num">Contract sum</th><th class="num">Omissions</th><th class="num">Additions</th><th class="num">Abortive</th><th class="num">Cumulative</th><th class="num">% of contract</th></tr></thead><tbody>
 ${sums.map(({k,s})=>`<tr class="link" data-open-package="${k.id}"><td><strong>${esc(k.code)}</strong></td><td>${esc(k.name)}</td><td>${esc(k.contractor)}</td><td>${esc(k.contract.type)}</td><td class="num">${money(s.contractSum)}</td><td class="num omit">${money(s.omissions)}</td><td class="num add">${money(s.additions)}</td><td class="num abort">${money(s.abortive)}</td><td class="num">${money(s.cumulative)}</td><td class="num">${(s.pct*100).toFixed(2)}%</td></tr>`).join('')}
 </tbody></table></div>`}
function packageView(){const k=K(),tab=view.tab||'changes',s=E.packageSummary(k);
 const tabs=[['changes','Changes'],['contract','Contract and documents'],['boq','BOQ'],['log','Change log'],['summary','Summary']];
 return `<div class="row between"><div class="stack" style="gap:4px"><h1>${esc(k.code)} ${esc(k.name)}</h1><p class="muted">${esc(k.contractor)} · ${esc(k.contract.type==='Other'?k.contract.typeOther||'Other':k.contract.type)}</p></div><div class="row"><button class="btn primary" data-act="newChange">New change</button><button class="btn" data-act="exportLog">Export change log</button></div></div>
 <div class="titleblock"><div><span class="tb-label">Contract sum</span><span class="tb-val mono">${money(s.contractSum)}</span></div><div><span class="tb-label">Approved VOs</span><span class="tb-val mono">${money(s.approved)}</span></div><div><span class="tb-label">Pending assessments</span><span class="tb-val mono">${money(s.pending)}</span></div><div><span class="tb-label">Cumulative</span><span class="tb-val mono">${money(s.cumulative)}</span></div><div><span class="tb-label">Adjusted sum</span><span class="tb-val mono">${money(s.adjusted)}</span></div></div>
 <div class="tabs" role="tablist">${tabs.map(([id,l])=>`<button role="tab" aria-selected="${id===tab}" data-tab="${id}">${l}</button>`).join('')}</div>
 ${({changes:changesTab,contract:contractTab,boq:boqTab,log:logTab,summary:summaryTab})[tab]()}`}
function statusChip(st){const c=st==='Approved'?'ok':st==='Cancelled'?'stop':'wait';return `<span class="chip ${c}">${esc(st||'-')}</span>`}
function changesTab(){const k=K();const over=E.boqOveromissions(k);
 return `${alerts(over)}<div class="scroll"><table><thead><tr><th>Change</th><th>Title</th><th>Chain</th><th>Status</th><th class="num">AAA net</th><th class="num">Contractor</th><th class="num">Approved</th></tr></thead><tbody>
 ${k.changes.map(c=>{const v=E.changeValue(c,k),l=E.latestStage(c)||{};return `<tr class="link" data-open-change="${c.id}"><td class="mono">${esc(c.id)}</td><td>${esc(c.title)}</td><td>${esc((c.stages||[]).map(s=>s.kind).join(' > '))}</td><td>${statusChip(l.status)}</td><td class="num">${money(v.assessed)}</td><td class="num">${money(v.contractor)}</td><td class="num">${money(v.approved)}</td></tr>`}).join('')||'<tr><td colspan="7" class="muted">No changes yet. Choose New change to raise the first one.</td></tr>'}
 </tbody></table></div>`}
function alerts(list){return list&&list.length?`<div class="alerts">${list.map(a=>`<div class="alert ${a.level==='error'?'error':''}">${esc(a.line?a.line+': ':'')}${esc(a.text)}</div>`).join('')}</div>`:''}
function fld(label,bind,val,type='text',opts){const id='f-'+bind.replace(/\W/g,'-');const ctl=opts?`<select id="${id}" data-bind="${bind}">${opts.map(o=>`<option ${o===val?'selected':''}>${esc(o)}</option>`).join('')}</select>`:type==='area'?`<textarea id="${id}" data-bind="${bind}">${esc(val)}</textarea>`:`<input id="${id}" type="${type}" data-bind="${bind}" value="${esc(val)}">`;return `<label class="field"><span>${label}</span>${ctl}</label>`}
function contractTab(){const k=K(),c=k.contract;const yn=['Yes','No'];
 return `<div class="sheet stack"><h2>Contract profile</h2><p class="small muted">Enter the pricing terms once. Quantities and new rates in this package follow them.</p>
 <div class="grid">${fld('Package code','pkg.code',k.code)}${fld('Package name','pkg.name',k.name)}${fld('Contractor','pkg.contractor',k.contractor)}${fld('Contract type','c.type',c.type,'',CONTRACTS)}${c.type==='Other'?fld('Describe the contract','c.typeOther',c.typeOther):''}${fld('OH&P on new rates %','c.markupPct',c.markupPct,'number')}${fld('VAT %','c.vatPct',c.vatPct,'number')}${fld('Design fees included in rates','c.designFeesIncluded',c.designFeesIncluded,'',yn)}${fld('IFC same as IFT','c.iftIsIfc',c.iftIsIfc,'',yn)}${fld('Geotechnical report in the tender','c.geotech',c.geotech,'',yn)}</div>
 <div class="grid">${fld('Variation pricing clause','c.pricingClause',c.pricingClause,'area')}${fld('Payment clause','c.paymentClause',c.paymentClause,'area')}${fld('Notes','c.notes',c.notes,'area')}</div></div>
 ${aiPanel('contract','Read contract terms with AI','Send the variation, payment and fee clauses to AI and review the extracted terms here.')}
 <div class="sheet stack"><h2>Package documents</h2><p class="small muted">Files are registered here by name and revision. They are not uploaded anywhere.</p><div class="scroll"><table><thead><tr><th>Document</th><th>File</th><th>Rev</th><th>Date</th><th></th></tr></thead><tbody>
 ${DOC_SLOTS.map(slot=>{const list=k.docs.filter(d=>d.category===slot);return (list.length?list:[null]).map(d=>`<tr><td>${esc(slot)}</td>${d?`<td>${esc(d.name)}</td><td>${esc(d.rev)}</td><td>${esc(d.date)}</td><td><button class="ghost btn" data-del-doc="${esc(k.docs.indexOf(d))}">Remove</button></td>`:`<td class="muted">Not registered</td><td></td><td></td><td></td>`}</tr>`).join('')+`<tr><td></td><td colspan="4"><label class="btn">Add file<input type="file" hidden data-doc="${esc(slot)}"></label></td></tr>`}).join('')}
 </tbody></table></div></div>`}
function boqTab(){const k=K(),total=k.boq.reduce((a,b)=>a+E.num(b.qty)*E.num(b.rate),0);
 return `<div class="row"><label class="btn">Import BOQ from Excel<input type="file" accept=".xlsx" hidden data-act="importBoq"></label><button class="btn" data-act="tplBoq">Download BOQ template</button><button class="btn" data-act="addBoq">Add item</button></div>
 <div class="scroll"><table><thead><tr><th>Code</th><th style="min-width:280px">Description</th><th>Unit</th><th class="num">Qty</th><th class="num">Rate</th><th class="num">Amount</th><th>Discipline</th><th></th></tr></thead><tbody>
 ${k.boq.map((b,i)=>`<tr><td><input aria-label="Code" data-bind="boq.${i}.code" value="${esc(b.code)}"></td><td><input aria-label="Description" data-bind="boq.${i}.desc" value="${esc(b.desc)}"></td><td><input aria-label="Unit" data-bind="boq.${i}.unit" value="${esc(b.unit)}" style="width:64px"></td><td><input aria-label="Quantity" class="num" type="number" data-bind="boq.${i}.qty" value="${esc(b.qty)}" style="width:100px"></td><td><input aria-label="Rate" class="num" type="number" data-bind="boq.${i}.rate" value="${esc(b.rate)}" style="width:100px"></td><td class="num">${money(E.num(b.qty)*E.num(b.rate))}</td><td><input aria-label="Discipline" data-bind="boq.${i}.discipline" value="${esc(b.discipline)}" style="width:110px"></td><td><button class="ghost btn" data-del-boq="${i}">Remove</button></td></tr>`).join('')}
 <tr class="total"><td colspan="5">Total</td><td class="num">${money(total)}</td><td colspan="2"></td></tr></tbody></table></div>`}
function logTab(){const k=K(),rows=E.logRows(k);const st=s=>s&&s.no?`${esc(s.no)}<br><span class="small muted">${esc(s.date)}</span>`:'-';
 return `<div class="scroll"><table><thead><tr><th>Change</th><th style="min-width:240px">Title</th><th>Reason</th><th>DCR</th><th>Notice</th><th>CR</th><th>SI</th><th>VO</th><th>Status</th><th class="num">Contractor</th><th class="num">AAA assessed</th><th class="num">Approved</th><th class="num">Contractor less AAA</th></tr></thead><tbody>
 ${rows.map(r=>`<tr class="link" data-open-change="${r.id}"><td class="mono">${esc(r.id)}</td><td>${esc(r.title)}</td><td>${esc(r.reason)}<br><span class="small muted">${esc(r.reasonRef)}</span></td><td>${st(r.dcr)}</td><td>${st(r.nov.no?r.nov:r.claim)}</td><td>${st(r.cr)}</td><td>${r.si.length?r.si.map(st).join('<br>'):'-'}</td><td>${st(r.vo)}</td><td>${statusChip(r.status)}</td><td class="num">${money(r.contractor)}</td><td class="num">${money(r.assessed)}</td><td class="num">${money(r.approved)}</td><td class="num">${money(r.variance)}</td></tr>`).join('')}
 </tbody></table></div>`}
function summaryTab(){const k=K(),s=E.packageSummary(k),ent=Object.entries(s.byDiscipline),max=Math.max(1,...ent.map(e=>Math.abs(e[1])));
 return `<div class="grid"><div class="sheet stack"><h2>Variation build-up</h2><table><tbody><tr><td>Omissions</td><td class="num omit">${money(s.omissions)}</td></tr><tr><td>Additions</td><td class="num add">${money(s.additions)}</td></tr><tr><td>Abortive work</td><td class="num abort">${money(s.abortive)}</td></tr><tr><td>Not broken down into items</td><td class="num">${money(s.unanalysed)}</td></tr><tr><td>Cumulative after approved VO values</td><td class="num">${money(s.cumulative)}</td></tr></tbody></table></div>
 <div class="sheet stack"><h2>By discipline</h2><div class="bars">${ent.map(([d,v])=>`<div class="bar"><span>${esc(d)}</span><span><i class="${v<0?'neg':''}" style="width:${Math.abs(v)/max*100}%"></i></span><span class="num">${money(v)}</span></div>`).join('')}</div></div></div>`}

function changeView(){const k=K(),c=C(),calc=E.computeChange(c,k),tab=view.tab||'scope';
 const tabs=[['scope','Scope and quantities'],['rates','Rates'],['compare','Contractor vs AAA'],['chain','Chain and instructions']];
 const checks=E.chainChecks(c).concat(calc.flags);
 return `<div class="row between"><div class="stack" style="gap:4px;flex:1;min-width:260px"><span class="mono small muted">${esc(c.id)}</span><h1>${esc(c.title)}</h1></div><div class="row"><button class="btn primary" data-act="exportVA">Export assessment</button><button class="btn" data-act="convert">Move to next stage</button></div></div>
 <div class="titleblock"><div><span class="tb-label">Contract rule</span><span class="tb-val">${esc(k.contract.type)}</span><span class="small muted"> ${esc(ruleText(k))}</span></div><div><span class="tb-label">Omissions</span><span class="tb-val mono omit">${money(calc.omissions)}</span></div><div><span class="tb-label">Additions</span><span class="tb-val mono add">${money(calc.additions)}</span></div><div><span class="tb-label">Abortive</span><span class="tb-val mono abort">${money(calc.abortiveTotal)}</span></div><div><span class="tb-label">Net variation</span><span class="tb-val mono">${money(calc.net)}</span></div></div>
 ${c.imported&&!c.lines.length?'<div class="alert">Imported from the cost report at log value. Add omission and addition items to assess it.</div>':checks.length?alerts(checks):'<div class="alert good">All checks passed for this change.</div>'}
 <div class="tabs" role="tablist">${tabs.map(([id,l])=>`<button role="tab" aria-selected="${id===tab}" data-tab="${id}">${l}</button>`).join('')}</div>
 ${({scope:scopeTab,rates:ratesTab,compare:compareTab,chain:chainTab})[tab](calc)}`}
function ruleText(k){const b=E.measurementBasis(k.contract.type);return b==='lumpsum'?'Full replacement keeps BOQ quantities':b==='remeasured'?'New items use actual take-off':'Actual take-off'}
function boqOptions(k,sel){return `<option value="">None</option>`+k.boq.map(b=>`<option value="${esc(b.code)}" ${b.code===sel?'selected':''}>${esc(b.code)} ${esc(b.desc.slice(0,38))}</option>`).join('')}
function lineRow(l,raw,k,abort){const i=raw?K().changes.find(x=>x.id===view.c).lines.indexOf(raw):-1;
 if(l.action==='Abortive')return `<tr><td><span class="chip Abortive">Abortive</span></td><td>${esc(l.desc)}</td><td>${esc(l.unit)}</td><td class="small muted">${esc(l.qtyBasis)}</td><td></td><td class="num">${money(l.qty)}</td><td class="num">${money(l.rate)}</td><td class="num abort">${money(l.amount)}</td><td></td></tr>`;
 const ai=l.source==='AI'?`<br><label class="small"><input type="checkbox" data-bind="line.${i}.verified" ${l.verified?'checked':''}> <span class="chip ai">AI</span> verified</label>`:'';
 const omit=l.action==='Omission';
 return `<tr><td><span class="chip ${l.action}">${l.action}</span>${ai}</td>
 <td style="min-width:230px">${omit?`<select aria-label="BOQ item" data-bind="line.${i}.boqCode">${boqOptions(k,l.boqCode)}</select><div class="small muted">${esc(l.desc)}</div>`:`<input aria-label="Description" data-bind="line.${i}.desc" value="${esc(raw.desc||'')}">${''}<div class="small muted row" style="margin-top:3px"><span>Replaces</span><select aria-label="Replaced BOQ item" data-bind="line.${i}.replacesCode" style="flex:1">${boqOptions(k,l.replacesCode)}</select></div>`}</td>
 <td>${omit?esc(l.unit):`<input aria-label="Unit" data-bind="line.${i}.unit" value="${esc(raw.unit||'')}" style="width:56px">`}</td>
 <td style="min-width:150px">${omit?`<select aria-label="Scope" data-bind="line.${i}.scope"><option value="full" ${l.scope==='full'?'selected':''}>Full item</option><option value="partial" ${l.scope==='partial'?'selected':''}>Part of item</option></select>`:''}<div class="small muted">${esc(l.qtyBasis)}</div></td>
 <td><input aria-label="Take-off" class="num" type="number" data-bind="line.${i}.takeoffQty" value="${esc(raw.takeoffQty)}" style="width:92px">${omit&&abort?`<div class="small muted">Executed</div><input aria-label="Executed quantity" class="num" type="number" data-bind="line.${i}.executedQty" value="${esc(raw.executedQty||'')}" style="width:92px">`:''}</td>
 <td class="num">${money(l.qty)}</td><td class="num">${money(l.rate)}</td><td class="num ${omit?'omit':'add'}">${money(l.amount)}</td><td><button class="ghost btn" data-del-line="${i}">Remove</button></td></tr>`}
function scopeTab(calc){const k=K(),c=C(),abort=c.abortive&&c.abortive.status==='Yes';const raw=id=>c.lines.find(x=>x.id===id);
 const band=(t,f)=>{const ls=calc.lines.filter(f);return ls.length?`<tr class="band"><td colspan="9">${t}</td></tr>`+ls.map(l=>lineRow(l,raw(l.id),k,abort)).join(''):''};
 return `<div class="row"><button class="btn" data-add-line="Omission">Add omission</button><button class="btn" data-add-line="Addition">Add addition</button></div>
 <div class="scroll"><table><thead><tr><th>Type</th><th>Item</th><th>Unit</th><th>Quantity rule</th><th class="num">Take-off</th><th class="num">Qty used</th><th class="num">Rate</th><th class="num">Amount</th><th></th></tr></thead><tbody>
 ${band('Omissions',l=>l.action==='Omission')}${band('Additions',l=>l.action==='Addition')}${band('Abortive work',l=>l.action==='Abortive')}
 <tr class="total"><td colspan="7">Net variation</td><td class="num">${money(calc.net)}</td><td></td></tr></tbody></table></div>
 <div class="sheet stack"><h2>Quantities</h2><p class="small muted">Pick any route. All three produce lines above that you can check before they count.</p>
 <div class="grid"><div class="route"><h3>Enter or mark up yourself</h3><p class="small muted">Type the take-off in the table above.</p></div>
 <div class="route"><h3>Upload take-off</h3><p class="small muted">Excel or CostX export with Code, Description, Unit, Original Qty, Revised Qty. The tool checks it against the BOQ.</p><div class="row"><label class="btn">Upload take-off<input type="file" accept=".xlsx" hidden data-act="importTakeoff"></label><button class="btn" data-act="tplTakeoff">Template</button></div></div>
 <div class="route"><h3>AI take-off</h3><p class="small muted">AI reads old and new PDF drawings and proposes quantities, marked for your verification.</p></div></div>
 ${takeoffRows?takeoffTable():''}</div>
 ${aiPanel('takeoff','AI take-off from drawings','Attach the original and revised PDF drawings. Every quantity comes back unverified.',true)}
 ${aiPanel('breakdown','Break down the change description','AI turns the general description into omission and addition items and lists items that may also be affected.')}
 <div class="sheet stack"><h2>Abortive work</h2><div class="grid">${fld('Executed before the instruction, per consultant','ab.status',(c.abortive||{}).status||'Not applicable','',['Not applicable','No','Yes'])}${fld('Confirmed by','ab.by',(c.abortive||{}).by||'')}${fld('Reference','ab.ref',(c.abortive||{}).ref||'')}</div><p class="small muted">When this is Yes, enter the executed quantity on each omission. Add demolition as an addition.</p></div>`}
function takeoffTable(){return `<div class="scroll"><table><thead><tr><th>Code</th><th>Description</th><th class="num">Original</th><th class="num">Revised</th><th class="num">Change</th><th>Result</th><th>Check</th></tr></thead><tbody>${takeoffRows.map(r=>`<tr><td>${esc(r.code)}</td><td>${esc(r.desc||(r.boq&&r.boq.desc)||'')}</td><td class="num">${money(r.originalQty)}</td><td class="num">${money(r.revisedQty)}</td><td class="num">${money(r.delta)}</td><td>${r.action?`<span class="chip ${r.action}">${r.action}</span>`:'No change'}</td><td class="small">${esc(r.flags.join('; '))||'OK'}</td></tr>`).join('')}</tbody></table></div><div class="row"><button class="btn primary" data-act="applyTakeoff">Create lines from this take-off</button></div>`}
function ratesTab(calc){const k=K(),c=C();const adds=calc.lines.filter(l=>l.action==='Addition');
 return `<p class="small muted">Rate order: BOQ item, similar item, derived from a BOQ item, new rate with build-up or quotation. New rates: supply, install, transport and labour are added up, then ${k.contract.markupPct||0}% OH&P from the contract profile is added. BOQ and derived rates are all-in, so no OH&P is added.</p>${adds.map(l=>{const raw=c.lines.find(x=>x.id===l.id),i=c.lines.indexOf(raw),src=raw.rateSource||'Manual';
 return `<div class="sheet stack"><div class="row between"><h3>${esc(l.desc||'New item')}</h3><span class="mono">${money(l.rate)} / ${esc(l.unit)}</span></div><div class="grid"><label class="field"><span>Rate source</span><select data-bind="line.${i}.rateSource">${['BOQ','Similar','Derived','New','Manual'].map(o=>`<option ${o===src?'selected':''}>${o}</option>`).join('')}</select></label>
 ${['BOQ','Similar','Derived'].includes(src)?`<label class="field"><span>BOQ reference</span><select data-bind="line.${i}.rateRef">${boqOptions(k,raw.rateRef)}</select></label>`:''}${src==='Derived'?`<label class="field"><span>Factor</span><input type="number" step="0.01" data-bind="line.${i}.factor" value="${esc(raw.factor)}"></label><label class="field"><span>Derivation (areas, lengths, reasoning)</span><input data-bind="line.${i}.derivation" value="${esc(raw.derivation)}"></label>`:''}${src==='Manual'||src==='New'?`<label class="field"><span>Rate if no build-up</span><input type="number" data-bind="line.${i}.rate" value="${esc(raw.rate)}"></label>`:''}${src==='New'?`<label class="field"><span>Quotation reference</span><input data-bind="line.${i}.quoteRef" value="${esc(raw.quoteRef)}"></label>`:''}</div>
 <p class="small muted">${esc(l.rateBasis)}</p>
 ${src==='New'?`<div class="scroll"><table><thead><tr><th>Type</th><th>Build-up item</th><th>Unit</th><th class="num">Qty per unit</th><th class="num">Rate</th><th class="num">Amount</th><th></th></tr></thead><tbody>${(raw.breakdown||[]).map((b,j)=>`<tr><td><select aria-label="Type" data-bind="bd.${i}.${j}.cat">${['Supply','Install','Transport','Labour','Other'].map(o=>`<option ${o===b.cat?'selected':''}>${o}</option>`).join('')}</select></td><td><input aria-label="Item" data-bind="bd.${i}.${j}.item" value="${esc(b.item)}"></td><td><input aria-label="Unit" data-bind="bd.${i}.${j}.unit" value="${esc(b.unit)}" style="width:60px"></td><td><input aria-label="Quantity" class="num" type="number" step="any" data-bind="bd.${i}.${j}.qty" value="${esc(b.qty)}" style="width:90px"></td><td><input aria-label="Rate" class="num" type="number" step="any" data-bind="bd.${i}.${j}.rate" value="${esc(b.rate)}" style="width:90px"></td><td class="num">${money(E.num(b.qty)*E.num(b.rate))}</td><td><button class="ghost btn" data-del-bd="${i}.${j}">Remove</button></td></tr>`).join('')}<tr class="total"><td colspan="5">Direct cost</td><td class="num">${money(l.direct)}</td><td></td></tr></tbody></table></div><div><button class="btn" data-add-bd="${i}">Add build-up item</button></div>`:''}</div>`}).join('')||'<p class="muted">No additions on this change yet.</p>'}`}
function compareTab(calc){const c=C(),lines=calc.lines.filter(l=>l.action!=='Abortive');
 return `<p class="small muted">Enter the contractor's submitted quantity and rate. The tool shows the difference line by line.</p><div class="scroll"><table><thead><tr><th>Type</th><th style="min-width:240px">Item</th><th class="num">Contractor qty</th><th class="num">Contractor rate</th><th class="num">Contractor amount</th><th class="num">AAA qty</th><th class="num">AAA rate</th><th class="num">AAA amount</th><th class="num">Difference</th></tr></thead><tbody>
 ${lines.map(l=>{const raw=c.lines.find(x=>x.id===l.id),i=c.lines.indexOf(raw);return `<tr><td><span class="chip ${l.action}">${l.action}</span></td><td>${esc(l.desc)}</td><td><input aria-label="Contractor quantity" class="num" type="number" data-bind="line.${i}.contractorQty" value="${esc(raw.contractorQty)}" style="width:92px"></td><td><input aria-label="Contractor rate" class="num" type="number" data-bind="line.${i}.contractorRate" value="${esc(raw.contractorRate)}" style="width:92px"></td><td class="num">${money(l.contractorAmount)}</td><td class="num">${money(l.qty)}</td><td class="num">${money(l.rate)}</td><td class="num">${money(l.amount)}</td><td class="num">${l.contractorAmount==null?'-':money(E.round2(l.contractorAmount-l.amount))}</td></tr>`}).join('')}
 <tr class="total"><td colspan="4">Total</td><td class="num">${money(calc.contractorTotal)}</td><td colspan="2"></td><td class="num">${money(E.round2(lines.reduce((a,l)=>a+l.amount,0)))}</td><td class="num">${calc.contractorTotal==null?'-':money(E.round2(calc.contractorTotal-lines.reduce((a,l)=>a+l.amount,0)))}</td></tr></tbody></table></div>`}
function chainTab(){const c=C();const st=c.stages||[];
 return `<div class="sheet stack"><h2>Stages</h2><p class="small muted">One record from start to finish. The title carries through every stage. Any price move needs a reason.</p><div class="chain">${st.map((s,i)=>{const d=i?E.round2(E.num(s.amount)-E.num(st[i-1].amount)):null;return `${i?`<div class="link-delta">${d>0?'+':''}${money(d)}</div>`:''}<div class="stage"><strong style="font-family:var(--head);font-size:18px">${esc(s.kind)}</strong>${fldS(i,'no','Number',s.no)}${fldS(i,'date','Date',s.date,'date')}<label class="field"><span>Status</span><select data-bind="st.${i}.status">${[...new Set(STATUSES.concat(s.status||[]))].map(o=>`<option ${o===s.status?'selected':''}>${esc(o)}</option>`).join('')}</select></label>${fldS(i,'amount','Stage amount',s.amount,'number')}${s.kind==='VO'?fldS(i,'approved','Approved amount',s.approved,'number'):''}${i?`<label class="field"><span>Reason for move</span><textarea style="min-height:60px" data-bind="st.${i}.deltaReason">${esc(s.deltaReason)}</textarea></label>`:''}</div>`}).join('')}</div></div>
 <div class="sheet stack"><div class="row between"><h2>Site instructions</h2><button class="btn" data-act="addSi">Add instruction</button></div>${(c.si||[]).length?`<div class="scroll"><table><thead><tr><th>Number</th><th>Date</th><th>Reference</th><th></th></tr></thead><tbody>${c.si.map((s,i)=>`<tr><td><input aria-label="Number" data-bind="si.${i}.no" value="${esc(s.no)}"></td><td><input aria-label="Date" type="date" data-bind="si.${i}.date" value="${esc(s.date)}"></td><td><input aria-label="Reference" data-bind="si.${i}.ref" value="${esc(s.ref)}"></td><td><button class="ghost btn" data-del-si="${i}">Remove</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No site instructions on this change.</p>'}</div>
 <div class="sheet stack"><h2>Change details</h2><div class="grid">${fld('Title','ch.title',c.title)}${fld('Reason','ch.reason',c.reason,'',REASONS)}${fld('Reason reference','ch.reasonRef',c.reasonRef)}</div>${fld('General description','ch.description',c.description,'area')}</div>`}
function fldS(i,f,l,v,t='text'){return `<label class="field"><span>${l}</span><input type="${t}" data-bind="st.${i}.${f}" value="${esc(v)}"></label>`}

/* ---------- AI: free paste route and paid key route share one prompt ---------- */
const AI_SCHEMAS={
 breakdown:'{"lines":[{"action":"Omission|Addition","boqCode":"code or empty","desc":"item description","unit":"m2","scope":"full|partial","qty":0,"note":"why"}],"affected":["other items that may be affected"]}',
 takeoff:'{"lines":[{"action":"Omission|Addition","boqCode":"code or empty","desc":"item description","unit":"m2","scope":"full|partial","qty":0,"note":"drawing and method used"}],"affected":[]}',
 contract:'{"type":"Lump Sum|Re-measured|Cost Plus|Design & Build|Other","markupPct":0,"designFeesIncluded":"Yes|No","pricingClause":"clause number and text","paymentClause":"clause number and text"}'};
function aiPrompt(kind){const k=K(),c=C();const boq=k.boq.map(b=>`${b.code} | ${b.desc} | ${b.unit} | ${b.qty} | ${b.rate}`).join('\n');
 const head={breakdown:`You support a construction cost manager. Break this change into omitted and added BOQ items. Include hidden related items.\nChange title: ${c&&c.title}\nDescription: ${c&&c.description}\nContract type: ${k.contract.type}`,
  takeoff:`You support a construction cost manager. Compare the attached original and revised drawings for this change and measure what was removed and added. State the drawing used for each quantity. If a quantity cannot be read, leave qty as 0 and say why.\nChange title: ${c&&c.title}\nDescription: ${c&&c.description}`,
  contract:'Read the attached contract text. Extract the variation pricing terms, the combined overhead and profit percentage on new rates (markupPct), design fees and payment terms. Copy clause numbers exactly. Use 0 when a percentage is not stated.'}[kind];
 return `${head}\n${kind==='contract'?'':`\nBOQ (code | description | unit | qty | rate):\n${boq}\n`}\nReply with JSON only, in this shape:\n${AI_SCHEMAS[kind]}`}
function aiPanel(kind,title,hint,files){return `<details class="sheet" id="ai-${kind}"><summary><strong style="font:600 19px var(--head)">${title}</strong> <span class="small muted">${hint}</span></summary><div class="grid" style="margin-top:12px">
 <div class="route"><h3>Free, 3 steps</h3><p class="small"><strong>1.</strong> Copy the request. <strong>2.</strong> Open a chat and paste it${files||kind==='contract'?', with your PDF attached':''}. <strong>3.</strong> Paste the reply below. It is added automatically.</p><div class="row"><button class="btn primary" data-ai-copy="${kind}">1. Copy request</button><a class="btn" href="https://claude.ai/new" target="_blank" rel="noopener">Claude</a><a class="btn" href="https://chatgpt.com" target="_blank" rel="noopener">ChatGPT</a><a class="btn" href="https://gemini.google.com" target="_blank" rel="noopener">Gemini</a>${kind==='breakdown'?`<button class="btn" data-ai-sample="${kind}">Sample reply</button>`:''}</div><textarea id="ai-reply-${kind}" aria-label="AI reply" placeholder="3. Paste the AI reply here">${esc(aiText[kind]||'')}</textarea><div><button class="btn" data-ai-apply="${kind}">Add reply</button></div></div>
 <div class="route"><h3>One click, with an API key</h3><p class="small muted">Runs inside the tool. Add the key once in AI settings. Costs cents per use.</p>${files?`<input type="file" id="ai-files-${kind}" accept=".pdf" multiple aria-label="PDF drawings">`:kind==='contract'?`<input type="file" id="ai-files-${kind}" accept=".pdf" aria-label="Contract PDF">`:''}<div class="row"><button class="btn" data-ai-run="${kind}">Run with AI</button><button class="btn ghost" data-act="settings">AI settings</button></div></div></div></details>`}
async function aiRun(kind){const key=getKey(),host=window.claude&&await window.claude.use('sample').catch(()=>null);const prompt=aiPrompt(kind);const input=document.getElementById('ai-files-'+kind);const files=input?[...input.files]:[];
 if(!key&&host&&!files.length){toast('Running AI');const r=await host(prompt,{modelTier:'quick'});document.getElementById('ai-reply-'+kind).value=r.text;aiText[kind]=r.text;toast('Reply received. Review it, then choose Apply reply.');return}
 if(!key){toast('Add your API key in AI settings, or use the free route.');openSettings();return}
 const content=[];for(const f of files){const b64=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]);r.onerror=no;r.readAsDataURL(f)});content.push({type:'document',source:{type:'base64',media_type:'application/pdf',data:b64}})}
 content.push({type:'text',text:prompt});toast('Running AI');
 const res=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers:{'content-type':'application/json','x-api-key':key,'anthropic-version':'2023-06-01','anthropic-dangerous-direct-browser-access':'true'},body:JSON.stringify({model:kind==='breakdown'?'claude-haiku-5-5':'claude-sonnet-5-5',max_tokens:4000,messages:[{role:'user',content}]})});
 const j=await res.json();if(!res.ok)throw new Error(j.error&&j.error.message||'The AI request failed.');
 const text=(j.content||[]).map(x=>x.text||'').join('');document.getElementById('ai-reply-'+kind).value=text;aiText[kind]=text;toast('Reply received. Review it, then choose Apply reply.')}
function aiApply(kind){const t=document.getElementById('ai-reply-'+kind).value;let j;try{j=E.parseAiJson(t)}catch(e){toast('That reply is not valid JSON. Ask the AI to reply with JSON only.');return}
 const k=K();
 if(kind==='contract'){['type','markupPct','designFeesIncluded','pricingClause','paymentClause'].forEach(f=>{if(j[f]!==undefined&&j[f]!=='')k.contract[f]=j[f]});save();render();toast('Contract terms filled. Check them against the contract.');return}
 const c=C();(j.lines||[]).forEach(l=>{const q=E.num(l.qty);c.lines.push({id:uid('l'),action:l.action==='Omission'?'Omission':'Addition',boqCode:l.action==='Omission'?l.boqCode||'':'',desc:l.desc||'',unit:l.unit||'',scope:l.scope==='full'?'full':'partial',takeoffQty:q||'',rateSource:'Manual',rate:'',source:'AI',verified:false,note:l.note||''})});
 if((j.affected||[]).length)c.description=(c.description||'')+'\nPossibly affected: '+j.affected.join('; ');
 aiText[kind]='';save();render();toast(`${(j.lines||[]).length} AI lines added. Verify each one.`)}
const SAMPLE_REPLY=()=>JSON.stringify({lines:[{action:'Addition',desc:'Skirting to match the changed finish',unit:'m',scope:'partial',qty:0,note:'Sample reply for demonstration'}],affected:['Door thresholds at the changed areas']},null,1);

/* ---------- Excel ---------- */
const INK='FF14212B',BAND='FFE5EEF6';
function hdr(ws,row){ws.getRow(row).eachCell(c=>{c.font={bold:true,color:{argb:'FFFFFFFF'}};c.fill={type:'pattern',pattern:'solid',fgColor:{argb:INK}};c.alignment={vertical:'middle',wrapText:true}})}
function nf(c){c.numFmt='#,##0.00;[Red]-#,##0.00'}
async function saveBook(wb,name){const buf=await wb.xlsx.writeBuffer();await saveBlob(name,new Blob([buf],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}))}
async function saveBlob(name,blob){const dl=window.claude&&await window.claude.use('downloads').catch(()=>null);if(dl){try{await dl.save({filename:name,data:blob});toast('Saved '+name)}catch(e){if(e&&e.code!=='declined')toast('The file could not be saved.')}return}
 const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),4000);toast('Saved '+name)}
async function exportVA(){const p=P(),k=K(),c=C(),calc=E.computeChange(c,k),wb=new ExcelJS.Workbook();wb.creator='VariLink';
 const ws=wb.addWorksheet('Variation Assessment',{views:[{showGridLines:false}]});ws.columns=[{width:12},{width:52},{width:8},{width:13},{width:14},{width:17},{width:44}];
 ws.getCell('A1').value='VARIATION ASSESSMENT';ws.getCell('A1').font={bold:true,size:15};
 const meta=[['Project',p.name],['Client',p.client],['Package',`${k.code} ${k.name}`],['Contractor',k.contractor],['Contract type',k.contract.type],['Change',c.id],['Title',c.title],['Reason',`${c.reason} (${c.reasonRef||'no reference'})`],['Chain',(c.stages||[]).map(s=>`${s.kind} ${s.no||''}`.trim()).join(' > ')],['Currency',p.currency]];
 meta.forEach((m,i)=>{ws.getCell(2+i,1).value=m[0];ws.getCell(2+i,1).font={bold:true};ws.getCell(2+i,2).value=m[1]});
 let r=13;const subtotal={};
 const section=(title,action)=>{const ls=calc.lines.filter(l=>l.action===action);if(!ls.length)return;ws.getCell(r,1).value=title;ws.getRow(r).font={bold:true};ws.getCell(r,1).fill={type:'pattern',pattern:'solid',fgColor:{argb:BAND}};r++;
  ws.getRow(r).values=['Item','Description','Unit','Quantity','Rate','Amount','Quantity basis'];hdr(ws,r);r++;const s=r;
  ls.forEach(l=>{ws.getRow(r).values=[l.boqCode||'New',l.desc,l.unit,l.qty,l.rate];ws.getCell(r,6).value={formula:`${l.sign<0?'-':''}D${r}*E${r}`,result:l.amount};ws.getCell(r,7).value=l.qtyBasis;[4,5,6].forEach(x=>nf(ws.getCell(r,x)));ws.getCell(r,2).alignment={wrapText:true};r++});
  ws.getCell(r,5).value='Sub-total';ws.getCell(r,5).font={bold:true};ws.getCell(r,6).value={formula:`SUM(F${s}:F${r-1})`,result:ls.reduce((a,l)=>a+l.amount,0)};ws.getCell(r,6).font={bold:true};nf(ws.getCell(r,6));subtotal[action]=r;r+=2};
 section('A. Omissions','Omission');section('B. Additions','Addition');section('C. Abortive work','Abortive');
 ws.getCell(r,5).value='Net variation';ws.getCell(r,5).font={bold:true};ws.getCell(r,6).value={formula:Object.values(subtotal).map(x=>'F'+x).join('+')||'0',result:calc.net};ws.getCell(r,6).font={bold:true};ws.getCell(r,6).border={top:{style:'thin'},bottom:{style:'double'}};nf(ws.getCell(r,6));r+=2;
 ws.getCell(r,1).value='Draft for review. Excludes VAT.';ws.getCell(r,1).font={italic:true};
 const ra=wb.addWorksheet('Rate Analysis');ra.columns=[{width:48},{width:14},{width:13},{width:15},{width:15},{width:44}];ra.getRow(1).values=['Addition item','Rate source','Reference','Qty per unit','Rate','Basis'];hdr(ra,1);let q=2;
 calc.lines.filter(l=>l.action==='Addition').forEach(l=>{ra.getRow(q).values=[l.desc,l.rateSource||'Manual',l.rateRef||l.quoteRef||'','',l.rate,l.rateBasis];nf(ra.getCell(q,5));ra.getRow(q).font={bold:true};q++;
  if(l.direct){const s=q;l.breakdown.forEach(b=>{ra.getRow(q).values=[`   ${b.cat||'Supply'}: ${b.item}`,b.unit,'',E.num(b.qty),E.num(b.rate)];ra.getCell(q,6).value={formula:`D${q}*E${q}`,result:E.round2(E.num(b.qty)*E.num(b.rate))};nf(ra.getCell(q,6));q++});
   const mk=E.num(k.contract.markupPct);ra.getCell(q,1).value='   Direct cost';ra.getCell(q,6).value={formula:`SUM(F${s}:F${q-1})`,result:l.direct};nf(ra.getCell(q,6));q++;
   ra.getCell(q,1).value=`   Rate with ${mk}% OH&P`;ra.getCell(q,6).value={formula:`ROUND(F${q-1}*(1+${mk}/100),2)`,result:l.rate};nf(ra.getCell(q,6));q++}q++});
 const cm=wb.addWorksheet('Contractor vs AAA');cm.columns=[{width:11},{width:48},{width:12},{width:12},{width:16},{width:12},{width:12},{width:16},{width:16}];cm.getRow(1).values=['Type','Item','Contractor qty','Contractor rate','Contractor amount','AAA qty','AAA rate','AAA amount','Difference'];hdr(cm,1);let z=2;
 calc.lines.filter(l=>l.action!=='Abortive').forEach(l=>{const rw=c.lines.find(x=>x.id===l.id),has=l.contractorAmount!=null;cm.getRow(z).values=[l.action,l.desc,has?E.num(rw.contractorQty):'',has?E.num(rw.contractorRate):'',has?{formula:`${l.sign<0?'-':''}C${z}*D${z}`,result:l.contractorAmount}:'',l.qty,l.rate,{formula:`${l.sign<0?'-':''}F${z}*G${z}`,result:l.amount},has?{formula:`E${z}-H${z}`,result:E.round2(l.contractorAmount-l.amount)}:''];[3,4,5,6,7,8,9].forEach(x=>nf(cm.getCell(z,x)));z++});
 cm.getCell(z,2).value='Total';cm.getRow(z).font={bold:true};['E','H','I'].forEach(cl=>{const i=cl.charCodeAt(0)-64;let tot=0;for(let y=2;y<z;y++){const v=cm.getCell(y,i).value;tot+=v&&v.result||0}cm.getCell(z,i).value={formula:`SUM(${cl}2:${cl}${z-1})`,result:E.round2(tot)};nf(cm.getCell(z,i))});
 const ch=wb.addWorksheet('Change Chain');ch.columns=[{width:15},{width:14},{width:13},{width:18},{width:16},{width:16},{width:50}];ch.getRow(1).values=['Stage','Number','Date','Status','Stage amount','Approved','Reason for move'];hdr(ch,1);(c.stages||[]).forEach((s,i)=>{ch.getRow(i+2).values=[s.kind,s.no,s.date,s.status,E.num(s.amount),s.approved===''?'':E.num(s.approved),s.deltaReason];nf(ch.getCell(i+2,5));nf(ch.getCell(i+2,6))});
 await saveBook(wb,`${c.id} Variation Assessment.xlsx`)}
function logSheet(wb,k,name){const ws=wb.addWorksheet(name.slice(0,31));ws.columns=[{width:15},{width:44},{width:18},{width:12},{width:12},{width:12},{width:12},{width:12},{width:12},{width:12},{width:12},{width:18},{width:16},{width:16},{width:16},{width:16}];ws.getRow(1).values=['Change','Title','Reason','DCR','DCR date','Notice','CR','CR date','SI','VO','VO date','Status','Contractor','AAA assessed','Approved','Contractor less AAA'];hdr(ws,1);ws.views=[{state:'frozen',ySplit:1}];
 E.logRows(k).forEach((r,i)=>{const n=i+2;ws.getRow(n).values=[r.id,r.title,r.reason,r.dcr.no||'',r.dcr.date||'',r.nov.no||r.claim.no||'',r.cr.no||'',r.cr.date||'',r.si.map(s=>s.no).join(', '),r.vo.no||'',r.vo.date||'',r.status,r.contractor==null?'':r.contractor,r.assessed,r.approved==null?'':r.approved,r.contractor==null?'':{formula:`M${n}-N${n}`,result:r.variance}];[13,14,15,16].forEach(c=>nf(ws.getCell(n,c)));ws.getCell(n,2).alignment={wrapText:true}});return ws}
async function exportLog(){const wb=new ExcelJS.Workbook(),k=K();logSheet(wb,k,'Change Log');await saveBook(wb,`${k.code} Change Log.xlsx`)}
async function exportProjectLog(){const wb=new ExcelJS.Workbook(),p=P();const ws=wb.addWorksheet('Variation Summary');ws.columns=[{width:12},{width:32},{width:18},{width:18},{width:18},{width:18},{width:18},{width:18}];ws.getRow(1).values=['Package','Name','Contract sum','Omissions','Additions','Abortive','Approved + pending','Adjusted sum'];hdr(ws,1);
 p.packages.forEach((k,i)=>{const s=E.packageSummary(k),n=i+2;ws.getRow(n).values=[k.code,k.name,s.contractSum,s.omissions,s.additions,s.abortive,s.cumulative,{formula:`C${n}+G${n}`,result:s.adjusted}];[3,4,5,6,7,8].forEach(c=>nf(ws.getCell(n,c)))});
 p.packages.forEach(k=>logSheet(wb,k,k.code+' Log'));await saveBook(wb,`${p.name} Variation Summary.xlsx`)}
async function template(name,cols,rows){const wb=new ExcelJS.Workbook(),ws=wb.addWorksheet('Sheet1');ws.getRow(1).values=cols;hdr(ws,1);ws.columns=cols.map(()=>({width:18}));(rows||[]).forEach((r,i)=>ws.getRow(i+2).values=r);await saveBook(wb,name)}
async function readSheet(file){const wb=new ExcelJS.Workbook();await wb.xlsx.load(await file.arrayBuffer());const ws=wb.worksheets[0];const val=c=>{const v=c.value;return v&&typeof v==='object'?(v.result!==undefined?v.result:v.text||(v.richText||[]).map(t=>t.text).join('')):v};
 let head=null;const out=[];ws.eachRow(row=>{const cells=[];row.eachCell({includeEmpty:true},(c,i)=>cells[i]=val(c));if(!head){if(cells.some(c=>/code|item/i.test(String(c)))&&cells.some(c=>/qty|quantity/i.test(String(c))))head=cells.map(c=>String(c||'').trim().toLowerCase());return}const o={};head.forEach((h,i)=>{if(h)o[h]=cells[i]});out.push(o)});
 if(!head)throw new Error('No header row found. Use the template columns.');return out}
async function readAllSheets(file){const wb=new ExcelJS.Workbook();await wb.xlsx.load(await file.arrayBuffer());const val=c=>{const v=c.value;if(v instanceof Date)return v;return v&&typeof v==='object'?(v.result!==undefined?v.result:v.text||(v.richText||[]).map(t=>t.text).join('')):v};return wb.worksheets.map(ws=>{const rows=[];ws.eachRow({includeEmpty:true},(row,n)=>{const c=[];for(let i=1;i<=ws.actualColumnCount+2&&i<=row.cellCount;i++)c[i-1]=val(row.getCell(i));rows[n-1]=c});return {name:ws.name,rows}})}
const pick=(o,...names)=>{for(const n of names)for(const k of Object.keys(o))if(k.includes(n))return o[k];return ''};

/* ---------- dialogs ---------- */
function dialog(html,onSubmit){const d=document.createElement('dialog');d.innerHTML=`<form method="dialog" class="stack" autocomplete="off">${html}<div class="row"><button class="btn primary" value="ok">Save</button><button class="btn" value="cancel" formnovalidate>Cancel</button></div></form>`;document.body.append(d);d.addEventListener('close',()=>{if(d.returnValue==='ok'){const data=Object.fromEntries([...new FormData(d.querySelector('form'))].map(([k,v])=>[k.replace(/^vl_/,''),v]));onSubmit(data)}d.remove()});d.showModal()}
const dInput=(n,l,v='',req=true,t='text')=>`<label class="field"><span>${l}</span><input name="vl_${n}" type="${t}" value="${esc(v)}" autocomplete="${t==='password'?'new-password':'off'}" ${req?'required':''}></label>`;
const dSel=(n,l,o,v)=>`<label class="field"><span>${l}</span><select name="${n}">${o.map(x=>`<option ${x===v?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
function openSettings(){dialog(`<h2>AI settings</h2><p class="small muted">The free route needs no key. For the paid route, paste an API key. It stays in this browser and goes only to the AI provider. Costs depend on use: a breakdown is under one US cent; a drawing take-off costs more with page count.</p>${dInput('key','API key',getKey(),false,'password')}`,d=>{setKey(d.key.trim());toast(d.key?'API key saved in this browser.':'API key removed.')})}
function newChange(){const k=K();dialog(`<h2>New change</h2>${dInput('title','Title')}${dSel('kind','Starts as',STAGES,'DCR')}${dInput('no','Reference number','',false)}${dSel('reason','Reason',REASONS,'Design change')}${dInput('reasonRef','Reason reference (letter, email or RFI)','',false)}<label class="field"><span>General description</span><textarea name="description"></textarea></label>`,d=>{const n=k.changes.length+1,id=`CE-${k.code.replace(/\W/g,'')}-${String(n).padStart(3,'0')}`.toUpperCase();k.changes.push({id,title:d.title,description:d.description,reason:d.reason,reasonRef:d.reasonRef,discipline:'',abortive:{status:'Not applicable'},si:[],lines:[],stages:[{kind:d.kind,no:d.no,date:new Date().toISOString().slice(0,10),status:'Draft',amount:0,approved:'',letterRef:'',deltaReason:''}]});save();go({p:view.p,k:view.k,c:id})})}
function convertStage(){const k=K(),c=C(),net=E.computeChange(c,k).net,last=E.latestStage(c)||{},moved=E.round2(net-E.num(last.amount));const next=last.kind==='VO'?'VO':last.kind==='CR'?'VO':'CR';
 dialog(`<h2>Move to next stage</h2><p>This keeps the title <strong>${esc(c.title)}</strong> and freezes today's assessment of <span class="mono">${money(net)}</span>.</p>${moved?`<div class="alert">This is ${money(moved)} different from ${esc(last.kind)} ${esc(last.no)}. Give the reason below.</div>`:''}${dSel('kind','New stage',STAGES,next)}${dInput('no','Number')}${dInput('date','Date',new Date().toISOString().slice(0,10),true,'date')}<label class="field"><span>Reason for move</span><textarea name="reason" ${moved?'required':''}></textarea></label>`,d=>{c.stages.push({kind:d.kind,no:d.no,date:d.date,status:'Draft',amount:net,approved:'',letterRef:'',deltaReason:d.reason});save();view.tab='chain';render();toast(`${d.kind} ${d.no} linked to ${c.id}`)})}

/* ---------- events ---------- */
function bind(path,v,el){const k=K(),c=C(),a=path.split('.');const nums=['takeoffQty','executedQty','contractorQty','contractorRate','rate','factor','qty','amount','approved','markupPct','vatPct'];const cast=f=>el.type==='checkbox'?el.checked:nums.includes(f)&&v!==''?Number(v):v;
 if(a[0]==='pkg')k[a[1]]=v;else if(a[0]==='c')k.contract[a[1]]=cast(a[1]);else if(a[0]==='boq')k.boq[+a[1]][a[2]]=cast(a[2]);else if(a[0]==='line')c.lines[+a[1]][a[2]]=cast(a[2]);else if(a[0]==='bd')c.lines[+a[1]].breakdown[+a[2]][a[3]]=cast(a[3]);else if(a[0]==='st')c.stages[+a[1]][a[2]]=cast(a[2]);else if(a[0]==='si')c.si[+a[1]][a[2]]=v;else if(a[0]==='ch')c[a[1]]=v;else if(a[0]==='ab'){c.abortive=c.abortive||{};c.abortive[a[1]]=v}
 save();render()}
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.bind){bind(t.dataset.bind,t.value,t);return}
 const f=t.files&&t.files[0];if(!f)return;
 try{ if(t.dataset.doc){const k=K();k.docs.push({category:t.dataset.doc,name:f.name,rev:'',date:new Date(f.lastModified).toISOString().slice(0,10)});save();render();return}
  if(t.dataset.act==='importJson'){const j=JSON.parse(await f.text());if(!j.id||!j.packages)throw new Error('This is not a VariLink project file.');const i=state.projects.findIndex(p=>p.id===j.id);i>=0?state.projects[i]=j:state.projects.push(j);save();go({p:j.id});return}
  if(t.dataset.act==='importReport'){toast('Reading the cost report');const sheets=await readAllSheets(f);const r=E.parseCostReport(sheets);const id=uid('p');dialog(`<h2>Import cost report</h2><p>Found ${r.packages.length} packages and ${r.rowsRead} logged changes.${r.unmatched.length?` Not matched: ${esc(r.unmatched.join(', '))}.`:''} The data stays in this browser.</p>${dInput('name','Project name','')}${dInput('client','Client','')}${dInput('currency','Currency','EGP')}`,x=>{state.projects.push({id,name:x.name,client:x.client,currency:x.currency,packages:r.packages});save();go({p:id})});t.value='';return}
  if(t.dataset.act==='importBoq'){const rows=await readSheet(f),k=K();const items=rows.map(o=>({code:String(pick(o,'code','item')||'').trim(),desc:String(pick(o,'desc')||''),unit:String(pick(o,'unit')||''),qty:E.num(pick(o,'qty','quantity')),rate:E.num(pick(o,'rate')),discipline:String(pick(o,'disc')||'General')})).filter(x=>x.code);k.boq=items;save();render();toast(`${items.length} BOQ items imported.`);return}
  if(t.dataset.act==='importTakeoff'){const rows=await readSheet(f);takeoffRows=E.compareTakeoff(rows.map(o=>({code:String(pick(o,'code','item')||'').trim(),desc:String(pick(o,'desc')||''),unit:String(pick(o,'unit')||''),originalQty:E.num(pick(o,'original','old')),revisedQty:E.num(pick(o,'revised','new'))})),K());render();return}
 }catch(err){toast(err.message||'The file could not be read.')}});
document.addEventListener('click',async e=>{const b=e.target.closest('button,tr.link');if(!b)return;const d=b.dataset,k=K(),c=C();
 try{
 if(d.delProject){const pr=state.projects.find(x=>x.id===d.delProject);return dialog(`<h2>Delete project</h2><p>This removes <strong>${esc(pr.name)}</strong> and all its packages from this browser. Type DELETE to confirm.</p>${dInput('ok','Confirmation')}`,x=>{if(x.ok.trim().toUpperCase()!=='DELETE')return toast('Project kept.');state.projects=state.projects.filter(y=>y.id!==pr.id);save();go({});toast('Project deleted.')})}
 if(d.go==='home')return go({});if(d.go==='p')return go({p:view.p});if(d.go==='k')return go({p:view.p,k:view.k});
 if(d.openProject)return go({p:d.openProject});if(d.openPackage)return go({p:view.p,k:d.openPackage});if(d.openChange)return go({p:view.p,k:view.k,c:d.openChange});
 if(d.tab){view.tab=d.tab;try{location.hash='v-'+[view.p,view.k,view.c&&view.c.toLowerCase(),view.tab].map(x=>x||'x').join('-')}catch(x){}return render()}
 if(d.addLine){c.lines.push(d.addLine==='Omission'?{id:uid('l'),action:'Omission',scope:'partial',boqCode:'',takeoffQty:''}:{id:uid('l'),action:'Addition',desc:'',unit:'',takeoffQty:'',rateSource:'BOQ',rateRef:''});save();return render()}
 if(d.delLine){c.lines.splice(+d.delLine,1);save();return render()}
 if(d.delBoq){k.boq.splice(+d.delBoq,1);save();return render()}
 if(d.delDoc){k.docs.splice(+d.delDoc,1);save();return render()}
 if(d.delSi){c.si.splice(+d.delSi,1);save();return render()}
 if(d.addBd){const l=c.lines[+d.addBd];l.breakdown=l.breakdown||[];l.breakdown.push({cat:'Supply',item:'',unit:'',qty:1,rate:0});save();return render()}
 if(d.delBd){const [i,j]=d.delBd.split('.');c.lines[+i].breakdown.splice(+j,1);save();return render()}
 if(d.aiCopy){const t=aiPrompt(d.aiCopy);try{await navigator.clipboard.writeText(t);b.textContent='Copied. Now paste it in the chat';toast('Request copied.')}catch(x){const ta=document.getElementById('ai-reply-'+d.aiCopy);ta.value=t;ta.select();toast('Copy this request from the box.')}return}
 if(d.aiSample){document.getElementById('ai-reply-'+d.aiSample).value=SAMPLE_REPLY();return aiApply(d.aiSample)}
 if(d.aiApply)return aiApply(d.aiApply);if(d.aiRun)return await aiRun(d.aiRun);
 switch(d.act){
  case 'settings':return openSettings();
  case 'newProject':return dialog(`<h2>New project</h2>${dInput('name','Project name')}${dInput('client','Client')}${dInput('currency','Currency','EGP')}`,x=>{const id=uid('p');state.projects.push({id,name:x.name,client:x.client,currency:x.currency,packages:[]});save();go({p:id})});
  case 'newPackage':return dialog(`<h2>New package</h2>${dInput('code','Package code','PK-')}${dInput('name','Package name')}${dInput('contractor','Contractor')}${dSel('type','Contract type',CONTRACTS,'Lump Sum')}`,x=>{const id=uid('k');P().packages.push({id,code:x.code,name:x.name,contractor:x.contractor,contract:{type:x.type,typeOther:'',markupPct:30,vatPct:14,designFeesIncluded:'No',iftIsIfc:'Yes',geotech:'Yes',pricingClause:'',paymentClause:'',notes:''},docs:[],boq:[],changes:[]});save();go({p:view.p,k:id,tab:'contract'})});
  case 'newChange':return newChange();case 'convert':return convertStage();
  case 'addBoq':k.boq.push({code:'',desc:'',unit:'',qty:0,rate:0,discipline:''});save();return render();
  case 'addSi':c.si=c.si||[];c.si.push({no:'',date:'',ref:''});save();return render();
  case 'exportVA':return await exportVA();case 'exportLog':return await exportLog();case 'exportProjectLog':return await exportProjectLog();
  case 'exportJson':{const p=P();return await saveBlob(`${p.name}.varilink.json`,new Blob([JSON.stringify(p,null,1)],{type:'application/json'}))}
  case 'tplBoq':return await template('BOQ template.xlsx',['Code','Description','Unit','Qty','Rate','Discipline'],[['F-101','Sample item','m2',100,250,'Finishes']]);
  case 'tplTakeoff':return await template('Take-off template.xlsx',['Code','Description','Unit','Original Qty','Revised Qty'],[['F-101','Sample item','m2',100,80]]);
  case 'applyTakeoff':{let n=0;takeoffRows.filter(r=>r.action).forEach(r=>{const q=Math.abs(r.delta);if(r.action==='Omission')c.lines.push({id:uid('l'),action:'Omission',scope:r.scope,boqCode:r.boq?r.code:'',takeoffQty:q});else c.lines.push({id:uid('l'),action:'Addition',desc:r.desc||(r.boq&&r.boq.desc)||'',unit:r.unit||(r.boq&&r.boq.unit)||'',takeoffQty:q,rateSource:r.boq?'BOQ':'Manual',rateRef:r.boq?r.code:'',discipline:r.boq&&r.boq.discipline});n++});takeoffRows=null;save();render();return toast(`${n} lines created.`)}
 }}catch(err){toast(err.message||'That action failed.')}});
window.addEventListener('hashchange',()=>{fromHash();render()});
document.addEventListener('input',e=>{const m=(e.target.id||'').match(/^ai-reply-(.+)/);if(m)aiText[m[1]]=e.target.value});
document.addEventListener('paste',e=>{const m=(e.target.id||'').match(/^ai-reply-(.+)/);if(m)setTimeout(()=>{if(/\{[\s\S]*\}/.test(e.target.value))aiApply(m[1])},0)});
$('#brand').addEventListener('click',()=>go({}));
fromHash();if(!view.p&&state.projects.length)view={p:state.projects[0].id,k:null,c:null,tab:null};render();
})();
